//! Sound: looping background music and spoken dialogue.
//!
//! The audio itself is generated by the editor through ComfyUI and kept
//! beside the story, in its `audio` folder:
//!   music_<track>.<ext>             a `track` of the story
//!   voice_<speaker>_<hash>.<ext>    one line of dialogue, keyed by its text
//! A line whose words change gets a new name, so an old recording is never
//! played for new text. Anything missing is simply silent.

use std::path::{Path, PathBuf};

/// Formats the game can play, in the order they are looked for.
pub const EXTENSIONS: [&str; 4] = ["flac", "mp3", "ogg", "wav"];

/// Where a story keeps its sound: beside the story file.
pub fn audio_dir(story: &Path) -> PathBuf {
    story.parent().unwrap_or(Path::new(".")).join("audio")
}

/// File name (without extension) of the recording of one line.
pub fn voice_stem(who: &str, text: &str) -> String {
    let mut h = 0xcbf2_9ce4_8422_2325u64;
    for b in who.bytes().chain([b'\n']).chain(text.trim().bytes()) {
        h = (h ^ b as u64).wrapping_mul(0x0100_0000_01b3);
    }
    format!("voice_{}_{:012x}", who, h & 0xFFFF_FFFF_FFFF)
}

pub fn music_stem(track: &str) -> String {
    format!("music_{}", track)
}

/// The audio file with this stem, if one exists in any playable format.
pub fn find(dir: &Path, stem: &str) -> Option<PathBuf> {
    EXTENSIONS.iter().map(|ext| dir.join(format!("{}.{}", stem, ext))).find(|p| p.is_file())
}

/// Plays music and voices. Without a sound device (or built without the
/// `audio` feature) every call is a silent no-op, and `log` still records
/// what would have played.
pub struct Audio {
    dir: Option<PathBuf>,
    pub muted: bool,
    /// What was started, in order: "music calm", "music off", "voice p ...".
    pub log: Vec<String>,
    music: String,
    #[cfg(feature = "audio")]
    out: Option<Output>,
}

#[cfg(feature = "audio")]
struct Output {
    _stream: rodio::OutputStream,
    handle: rodio::OutputStreamHandle,
    music: Option<rodio::Sink>,
    voice: Option<rodio::Sink>,
}

#[cfg(feature = "audio")]
const MUSIC_VOLUME: f32 = 0.35;

impl Audio {
    /// `dir` is the story's audio folder; `device` false keeps it silent
    /// (headless runs).
    pub fn new(dir: Option<PathBuf>, device: bool) -> Audio {
        let dir = dir.filter(|d| d.is_dir());
        #[cfg(feature = "audio")]
        let out = if device && dir.is_some() {
            rodio::OutputStream::try_default().ok().map(|(stream, handle)| Output { _stream: stream, handle, music: None, voice: None })
        } else {
            None
        };
        let _ = device;
        Audio {
            dir,
            muted: false,
            log: Vec::new(),
            music: String::new(),
            #[cfg(feature = "audio")]
            out,
        }
    }

    /// Whether this story has any sound at all.
    pub fn available(&self) -> bool {
        self.dir.is_some()
    }

    pub fn current_music(&self) -> &str {
        &self.music
    }

    #[cfg(feature = "audio")]
    fn sink(out: &Output, path: &Path, looped: bool, volume: f32) -> Option<rodio::Sink> {
        use rodio::Source;
        let file = std::io::BufReader::new(std::fs::File::open(path).ok()?);
        let source = rodio::Decoder::new(file).ok()?;
        let sink = rodio::Sink::try_new(&out.handle).ok()?;
        sink.set_volume(volume);
        if looped {
            sink.append(source.repeat_infinite());
        } else {
            sink.append(source);
        }
        Some(sink)
    }

    /// Switch the background music; "" for silence. Asking for the track
    /// already playing changes nothing, so it carries across scenes.
    pub fn play_music(&mut self, track: &str) {
        if track == self.music {
            return;
        }
        self.music = track.to_string();
        let path = self.dir.as_ref().and_then(|d| find(d, &music_stem(track))).filter(|_| !track.is_empty());
        if self.dir.is_some() {
            self.log.push(match (&path, track.is_empty()) {
            (_, true) => "music off".to_string(),
            (Some(_), _) => format!("music {}", track),
                (None, _) => format!("music {} (not generated yet)", track),
            });
        }
        #[cfg(feature = "audio")]
        if let Some(out) = &mut self.out {
            out.music = path.and_then(|p| Self::sink(out, &p, true, if self.muted { 0.0 } else { MUSIC_VOLUME }));
        }
    }

    /// Speak a line, cutting off whatever was being said.
    pub fn say(&mut self, who: &str, text: &str) {
        let path = self.dir.as_ref().and_then(|d| find(d, &voice_stem(who, text)));
        #[cfg(feature = "audio")]
        if let Some(out) = &mut self.out {
            out.voice = None;
        }
        let Some(path) = path else { return };
        self.log.push(format!("voice {} {}", who, path.file_name().unwrap_or_default().to_string_lossy()));
        #[cfg(feature = "audio")]
        if let Some(out) = &mut self.out {
            out.voice = Self::sink(out, &path, false, if self.muted { 0.0 } else { 1.0 });
        }
    }

    pub fn stop_voice(&mut self) {
        #[cfg(feature = "audio")]
        if let Some(out) = &mut self.out {
            out.voice = None;
        }
    }

    pub fn toggle_mute(&mut self) {
        self.muted = !self.muted;
        #[cfg(feature = "audio")]
        if let Some(out) = &self.out {
            if let Some(m) = &out.music {
                m.set_volume(if self.muted { 0.0 } else { MUSIC_VOLUME });
            }
            if let Some(v) = &out.voice {
                v.set_volume(if self.muted { 0.0 } else { 1.0 });
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// A short, valid, silent WAV file.
    fn wav() -> Vec<u8> {
        let data = vec![0u8; 3200];
        let mut out = b"RIFF".to_vec();
        out.extend_from_slice(&(36 + data.len() as u32).to_le_bytes());
        out.extend_from_slice(b"WAVEfmt ");
        for v in [16u32.to_le_bytes().to_vec(), 1u16.to_le_bytes().to_vec(), 1u16.to_le_bytes().to_vec(), 8000u32.to_le_bytes().to_vec(), 16000u32.to_le_bytes().to_vec(), 2u16.to_le_bytes().to_vec(), 16u16.to_le_bytes().to_vec()] {
            out.extend_from_slice(&v);
        }
        out.extend_from_slice(b"data");
        out.extend_from_slice(&(data.len() as u32).to_le_bytes());
        out.extend_from_slice(&data);
        out
    }

    #[cfg(feature = "audio")]
    #[test]
    fn the_decoder_reads_what_the_tests_and_mock_server_produce() {
        use rodio::Source;
        let source = rodio::Decoder::new(std::io::Cursor::new(wav())).expect("decodes");
        assert_eq!((source.sample_rate(), source.channels()), (8000, 1));
        assert_eq!(source.count(), 1600);
    }

    #[test]
    fn a_line_is_keyed_by_speaker_and_words() {
        let a = voice_stem("p", "Marlowe! Splendid.");
        assert_eq!(a, voice_stem("p", "  Marlowe! Splendid. "));
        assert_ne!(a, voice_stem("v", "Marlowe! Splendid."));
        assert_ne!(a, voice_stem("p", "Marlowe! Splendid"));
        assert!(a.starts_with("voice_p_") && a.len() == "voice_p_".len() + 12);
    }

    #[test]
    fn playback_follows_the_files_that_exist() {
        let dir = std::env::temp_dir().join(format!("bsas-audio-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        std::fs::write(dir.join("music_calm.wav"), wav()).unwrap();
        std::fs::write(dir.join(format!("{}.mp3", voice_stem("p", "Hello."))), b"x").unwrap();
        let mut audio = Audio::new(Some(dir.clone()), false);
        audio.play_music("calm");
        audio.play_music("calm"); // already playing: nothing new
        audio.say("p", "Hello.");
        audio.say("p", "Not recorded.");
        audio.play_music("storm");
        audio.play_music("");
        assert_eq!(audio.log.len(), 4);
        assert_eq!(audio.log[0], "music calm");
        assert!(audio.log[1].starts_with("voice p voice_p_") && audio.log[1].ends_with(".mp3"));
        assert_eq!(audio.log[2], "music storm (not generated yet)");
        assert_eq!(audio.log[3], "music off");
        let _ = std::fs::remove_dir_all(dir);
        // no folder: silent, and nothing is logged for voices
        let mut none = Audio::new(None, false);
        none.say("p", "Hello.");
        assert!(none.log.is_empty() && !none.available());
    }
}
